<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {useAuthenticationStore} from '../stores/authentication'
import {createProtectedClient} from '../api/protected'
import {useViewScope} from '../stores/view-scope'
import {shiftDate} from '../views/schedules/week'
import type {AppointmentSummary} from '../api/workspace-types'
import AppointmentActions from '../components/AppointmentActions.vue'
const auth=useAuthenticationStore(),api=createProtectedClient(),scope=useViewScope()
const roleNames:Record<string,string>={HEADQUARTERS:'总部管理',RECEPTION:'诊所前台',DENTIST:'牙医',CASHIER:'收费人员'}
const roles=computed(()=>Object.keys(roleNames).filter(role=>auth.canAccess(role,role==='HEADQUARTERS'?'analysis.read':'listAppointments')))
const role=ref(roles.value[0]??''),busy=ref(false),error=ref(''),states=ref<{status:string;count:number}[]|null>(null),visits=ref<AppointmentSummary[]>([]),tasks=ref<AppointmentSummary[]>([]),performance=ref<{quarterly_performance_id:string;dentist_id:string;calculation_status:string;incomplete_reasons:string[]}[]>([]),taskError=ref('')
const names:Record<string,string>={SCHEDULED:'待就诊',IN_PROGRESS:'诊疗中',COMPLETED:'待开费用凭据',INVOICED:'已生成费用凭据',CANCELLED:'已取消'}
const stats=computed(()=>[{label:'今日预约',value:states.value?.reduce((a,r)=>a+r.count,0)},...['SCHEDULED','IN_PROGRESS','COMPLETED'].map(status=>({label:names[status],value:states.value?states.value.find(r=>r.status===status)?.count??0:undefined}))])
const taskPath=computed(()=>role.value==='DENTIST'?'/clinical-treatment':role.value==='CASHIER'?'/invoicing':'/appointment-rescheduling')
let generation=0
async function load(){const version=++generation;states.value=null;visits.value=[];tasks.value=[];performance.value=[];error.value='';taskError.value='';if(!role.value)return;busy.value=true;
 const query=new URLSearchParams({role:role.value,start:scope.date+'T00:00:00+08:00',end:shiftDate(scope.date,1)+'T00:00:00+08:00'});if(scope.clinic)query.set('clinic_id',scope.clinic)
 try{const result=await api.get<{states:{status:string;count:number}[]}>('/api/v1/workspace/summary?'+query);if(version!==generation)return;states.value=result.states;if(role.value!=='HEADQUARTERS'){const page=await api.get<{items:AppointmentSummary[]}>('/api/v1/workspace/appointments?'+query+'&limit=6');if(version!==generation)return;visits.value=page.items}}catch{if(version===generation)error.value='概览暂未取得，请刷新或核对岗位和诊所授权。'}
 try{if(role.value==='HEADQUARTERS'){const now=new Date(scope.date+'T12:00:00Z'),m=Math.floor(now.getUTCMonth()/3)*3,year=now.getUTCFullYear();const q=new URLSearchParams({quarter_start:new Date(Date.UTC(year,m-3,1)).toISOString().slice(0,10),quarter_end:new Date(Date.UTC(year,m,1)).toISOString().slice(0,10),limit:'100'});const result=await api.get<{items:typeof performance.value}>('/api/v1/quarterly-performances?'+q);if(version===generation)performance.value=result.items.filter(r=>['INCOMPLETE','CALCULATED','DRAFT'].includes(r.calculation_status))}else{const q=new URLSearchParams({role:role.value,limit:'6'});if(scope.clinic)q.set('clinic_id',scope.clinic);if(role.value==='RECEPTION')q.set('review','reschedule');else q.set('status',role.value==='DENTIST'?'IN_PROGRESS':'COMPLETED');const page=await api.get<{items:AppointmentSummary[]}>('/api/v1/workspace/appointments?'+q);if(version===generation)tasks.value=page.items}}catch{if(version===generation)taskError.value='待办暂未取得，请进入对应工作区核对。'}finally{if(version===generation)busy.value=false}
}
watch([role,()=>scope.clinic,()=>scope.date],load)
onMounted(load)
</script>
<template><section class="dashboard-page"><div class="page-heading"><div><p class="eyebrow">ANDREW’S DENTAL · WORKSPACE</p><h1>把今天的工作，安排清楚</h1><p class="muted">{{scope.date}} · 先看需要处理的事，再查看业务情况。</p></div><div class="dashboard-actions"><RouterLink v-if="role==='HEADQUARTERS'" class="button-link" to="/quarterly-performance">查看季度核算</RouterLink><RouterLink v-if="auth.canAccess('RECEPTION','createAppointment')" class="button-link primary-link" to="/appointment-booking">进入预约工作台</RouterLink></div></div>
<div class="table-toolbar"><div class="filter-tabs" aria-label="岗位工作视图"><button v-for="r in roles" :key="r" :aria-pressed="role===r" @click="role=r">{{roleNames[r]}}</button></div><label>查看日期<input v-model="scope.date" type="date"></label><button :disabled="busy" @click="load">{{busy?'正在读取…':'刷新工作区'}}</button></div><p v-if="error" role="alert" class="error-message">{{error}}</p><p v-if="!roles.length" class="empty-state">当前岗位尚无概览查询能力，请从导航进入已授权业务。</p>
<template v-if="role"><div class="dashboard-stats"><article v-for="stat in stats" :key="stat.label"><span>{{stat.label}}</span><strong>{{stat.value===undefined?'未取得':stat.value}}</strong><small>所选范围 · 完整汇总 · 北京时间</small></article></div>
<div class="task-grid"><section class="surface"><div class="page-heading"><h2>需要处理</h2><span class="status-badge">{{roleNames[role]}}</span></div><p v-if="taskError" role="alert">{{taskError}}</p><template v-if="role==='HEADQUARTERS'"><div class="task-row"><div><strong>季度资料准备与来源缺项</strong><small>上一完整季度 · 按冻结人员及来源核验</small></div><RouterLink to="/quarterly-performance">进入核算 →</RouterLink></div><div class="task-row" v-for="row in performance.slice(0,4)" :key="row.quarterly_performance_id"><div><strong>{{row.calculation_status==='CALCULATED'?'计算完成，等待独立复核':'资料待核验'}}</strong><small>牙医 {{row.dentist_id}} · {{row.incomplete_reasons.length}} 项待核对</small></div><RouterLink to="/quarterly-performance">核对版本 →</RouterLink></div><p v-if="!performance.length&&!taskError&&!busy" class="empty-state">当前已读取版本没有待核验事项。</p><RouterLink v-if="auth.canAccess('HEADQUARTERS','cost.verify')" class="button-link" to="/cost-entries">核验成本来源</RouterLink></template><template v-else><h3>{{role==='DENTIST'?'本人进行中的就诊':role==='CASHIER'?'已完成治疗，等待费用核对':'停诊待处理预约'}}</h3><div v-for="item in tasks" :key="item.appointment_id" class="task-row"><div><strong>{{item.patient_name}}</strong><small>{{item.patient_number}} · {{item.clinic_name}}</small></div><RouterLink :to="{path:taskPath,query:{appointmentId:item.appointment_id}}">办理 →</RouterLink></div><p v-if="!tasks.length&&!busy&&!taskError" class="empty-state">当前没有待处理事项。</p><RouterLink :to="taskPath">查看完整队列 →</RouterLink></template></section>
<section class="surface"><h2>今日就诊进度</h2><div v-for="(label,status) in names" :key="status" class="task-row"><span>{{label}}</span><strong>{{states?states.find(r=>r.status===status)?.count??0:'未取得'}}</strong></div><p class="workspace-note">“已生成费用凭据”表示费用事实已开具，不代表已付款。</p></section></div>
<section v-if="role!=='HEADQUARTERS'" class="surface"><div class="page-heading"><h2>今日就诊安排</h2><RouterLink :to="role==='RECEPTION'?'/appointment-booking':taskPath">查看全部 →</RouterLink></div><div class="table-scroll"><table><thead><tr><th>时间</th><th>患者识别摘要</th><th>医生 / 诊所</th><th>状态</th><th>下一步</th></tr></thead><tbody><tr v-for="item in visits" :key="item.appointment_id"><td>{{new Date(item.scheduled_at).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'})}}</td><td>{{item.patient_name}}<small class="record-reference">{{item.patient_number}}</small></td><td>{{item.dentist_name}} · {{item.clinic_name}}</td><td>{{names[item.status]}}</td><td><AppointmentActions :appointment="item"/></td></tr></tbody></table></div><p v-if="!visits.length&&!error&&!busy" class="empty-state">所选日期暂无就诊安排。</p></section></template></section></template>
